class WorkersTransactionsView( generics.CreateAPIView, generics.ListAPIView):
	lookup_field = 'pk'
	serializer_class = WorkersTransactionsSerializer
	permission_classes = [AllowAny]


	def get_queryset(self):
		Workers = self.kwargs['workers']
		return WorkersTransactions.objects.filter(Officer_worker=Workers).order_by('-pk')

	# def filter_queryset(self, queryset):
	# 	queryset = super(WorkersTransactions, self).filter_queryset(queryset)
	# 	return queryset.order_by('-pk')

	
	def post(self, request, *args, **kwargs):
		data = request.data
		serializer = WorkersTransactionsSerializer(data=data)
		if serializer.is_valid(raise_exception=True):
			mon = serializer.save()
			Process = serializer.validated_data['Process']
			Officer_worker = serializer.validated_data['Officer_worker']
			Wakala_name = serializer.validated_data['Wakala_name']
			Mtandao_au_Benki = serializer.validated_data['Mtandao_au_Benki']
			# Directors_name = serializer.validated_data['Directors_name']
			Amount = serializer.validated_data['Amount']
			Jina_Mteja = serializer.validated_data['Jina_Mteja']
			Process = serializer.validated_data['Process']
				

			# goet = WorkerTransactionsOverall.objects.get_or_create(worker=Officer_worker)
			goe = WorkerTransactionsOverall.objects.get(worker=Officer_worker)
			goeh = WakalaWorkers.objects.get(user=Officer_worker)
			Wakalas = WakalaTransactionsOverall.objects.get(wakala=goeh.Branch_manager)
			Direct = DirectorTransactionsOverall.objects.get_or_create(Director=goeh.Mmiliki_wakala)
			Directors = DirectorTransactionsOverall.objects.get(Director=goeh.Mmiliki_wakala)
			goe.Total_pay = float(goe.Total_pay) + float(Amount)
			Wakalas.Total_pay = float(Wakalas.Total_pay) + float(Amount)
			Directors.Total_pay = float(Directors.Total_pay) + float(Amount)
			if Process == 'Kutoa':
				goe.Jumla_kinachotoka = float(goe.Jumla_kinachotoka) + float(Amount)
				goe.save()
				goe.Handled = float(goe.Jumla_Kinachoingia) - float(goe.Jumla_kinachotoka)
				Wakalas.Jumla_kinachotoka = float(Wakalas.Jumla_kinachotoka) + float(Amount)
				Directors.Jumla_kinachotoka = float(Directors.Jumla_kinachotoka) + float(Amount)
			else:
				goe.Jumla_Kinachoingia = float(goe.Jumla_Kinachoingia) + float(Amount)
				goe.save()
				goe.Handled = float(goe.Jumla_Kinachoingia) - float(goe.Jumla_kinachotoka)
				Wakalas.Jumla_Kinachoingia = float(Wakalas.Jumla_Kinachoingia) + float(Amount)
				Directors.Jumla_Kinachoingia = float(Directors.Jumla_Kinachoingia) + float(Amount)

			goe.save()
			Wakalas.save()
			Directors.save()
			return Response(serializer.validated_data)


