class DukaTimerReportView( generics.CreateAPIView, generics.ListAPIView):
	lookup_field = 'pk'
	serializer_class = DukaProductsSalesSerializer
	permission_classes = [AllowAny]
	# pagination_class = PostPageNumberPagination


	def get_queryset(self):
		comapany = self.kwargs['company']
		comp=comapany.split('/')
		company=comp[0]
		
		starta=comp[1]
		start=datetime.datetime.strptime(starta, '%Y-%m-%d').strftime('%Y-%m-%d %H:%M:%S')
		enda=comp[2]
		end=datetime.datetime.strptime(enda, '%Y-%m-%d').strftime('%Y-%m-%d %H:%M:%S')
		mob=DukaProductsSalesModel.objects.all()
		for m in mob:
			if m.company==company:
				if m.pk:
					mog=datetime.datetime.strptime(m.Tarehe, '%Y-%m-%d  %H:%M:%S').strftime('%Y-%m-%d %H:%M:%S')
					DukaProductsSalesModel.objects.filter(pk=m.pk, company=company).update(Tarehe=mog)
		return DukaProductsSalesModel.objects.filter(company=company,  Tarehe__gte=start, Tarehe__lte=end).order_by('-pk')


