class VyumbaView(generics.CreateAPIView, generics.ListAPIView):
	lookup_field = 'pk'
	serializer_class = VyumbaSerializer
	permission_classes = [AllowAny]


	def get_queryset(self):
		return VyumbaModel.objects.all()


	def post(self, request, *args, **kwargs):
		data = request.data
		serializer = VyumbaSerializer(data=data)
		if serializer.is_valid(raise_exception=True):
			mon = serializer.save()
			nyumbano = serializer.validated_data['nyumba_number']
			moma = Nyumba.objects.get(pk = int(nyumbano) )
			print(moma.kata)
			mon.simu = moma.simu
			mon.name = moma.name
			mon.kulipia = moma.Account_number
			mon.kata = moma.kata
			mon.wilaya = moma.wilaya
			mon.mkoa = moma.mkoa
			mon.save()
			return Response('moma', status=HTTP_200_OK)

	

