class OwnerDepositView( generics.CreateAPIView, generics.ListAPIView):
	lookup_field = 'pk'
	serializer_class =OwnerDepositSerializer
	permission_classes = [AllowAny]


	def get_queryset(self):
		return OwnerDeposit.objects.all()

	def post(self, request, *args, **kwargs):
		data = request.data
		serializer = OwnerDepositSerializer(data=data)
