class wapangajiView(generics.CreateAPIView, generics.ListAPIView):
	lookup_field = 'pk'
	serializer_class = WapangajiSerializer
	permission_classes = [AllowAny]


	def get_queryset(self):
		return wapangaji.objects.filter()
	
	def filter_queryset(self, queryset):
		# print('passsssssed')
		queryset = super(wapangajiView, self).filter_queryset(queryset)
		# print('passsssssed')
		return queryset.order_by('-pk')


	def post(self, request, *args, **kwargs):
		# print('1')
		data = request.data
		serializer = WapangajiSerializer(data=data)
		
		

		if serializer.is_valid(raise_exception=True):
			
			usere = serializer.validated_data['name']
			id = serializer.validated_data['nyumbaid']
			
			status = serializer.validated_data['status']
			
			muda = serializer.validated_data['muda']
			
			route = serializer.validated_data['route']
			miezi2 = serializer.validated_data['miezi2']
			miezi3 = serializer.validated_data['miezi3']
			mwezi1 = serializer.validated_data['mwezi1']
			baki = serializer.validated_data['baki']
			mwaka = serializer.validated_data['mwaka']
			kiasi = serializer.validated_data['kiasi']
			Owner = serializer.validated_data['House_Owner']
			filt = wapangaji.objects.filter(name=usere, info='delete').update(info='')
			morg = serializer.save()
			
			if route == 'payments':
				# print('passsesss')

				mwezi = serializer.validated_data['mwezi']
				mwc = MieziNyumba.objects.get_or_create(user = mwaka)
				usre = UserInfoNyumba.objects.get(user= usere)
				usrem = UserInfoNyumbaAllThem.objects.get(user= 'wote')
					
				mwzx = MieziNyumba.objects.filter(user__iexact=mwaka).update(mwezi=mwezi)
				mwex = MieziNyumba.objects.get(user__iexact = mwaka)
				# ow = HouseOwnerInfo.objects.get_or_create(user=Owner)
				own = Register.objects.get(Username=Owner)
