class TotalstockView(APIView):
	queryset = DukaProductsModel.objects.all()
	serializer_class = DukaProductsSerializer
	permission_classes = [AllowAny]
	
	def get(self, request, format=None):
		company = self.request.GET.get('company', None)
		momo = DukaProductsModel.objects.filter(company=company)
		momoall = DukaProductsModel.objects.all()
		for m in momoall:
			if m.company==company:
				if m.Selling_price:
					try:
						int(m.Selling_price)
						DukaProductsModel.objects.filter(pk=m.pk, company=company).update(Total_Available_product_wise=int(m.Number_of_products or 0)*int(m.Selling_price or 0))
					except ValueError:
						pass
					
				if m.Price_bought:
					try:
						int(m.Price_bought)
						DukaProductsModel.objects.filter(pk=m.pk, company=company).update(Total_brought_product_wise=int(m.Number_of_products or 0)*int(m.Price_bought or 0))
					except ValueError:
						pass
				if m.Profit:
					try:
						int(int(m.Profit))
						DukaProductsModel.objects.filter(pk=m.pk, company=company).update(Total_profit_product_wise=int(m.Number_of_products or 0)*int(m.Profit or 0))
					except ValueError:
						pass

		

		
	
		total = ( DukaProductsModel.objects.filter(company=company).aggregate(totol=Sum('Total_Available_product_wise'))['totol']) 
		total1 = ( DukaProductsModel.objects.filter(company=company).aggregate(totol1=Sum('Total_brought_product_wise'))['totol1']) 
		total2 = ( DukaProductsModel.objects.filter(company=company).aggregate(totol2=Sum('Total_profit_product_wise'))['totol2']) 
	
		total_stock_available=total
		total_stock_profit=total2
		total_stock_sold="779000"
		total_stock_bought=total1
		context={
            'total_stock_available':total_stock_available,
            'total_stock_profit':total_stock_profit,
            'total_stock_sold':total_stock_sold,
            'total_stock_bought':total_stock_bought
        }
