class ExpensesView(generics.CreateAPIView, generics.ListAPIView):
	# queryset = DukaMatumiziModels.objects.all()
	serializer_class = DukaMatumiziSerializer
	permission_classes = [AllowAny]

	def get_queryset(self):
		comapany = self.kwargs['company']

		comp=comapany.split('/')
		company=comp[0]
		
		starta=comp[1]
		start=datetime.datetime.strptime(starta, '%Y-%m-%d').strftime('%Y-%m-%d %H:%M:%S')
		enda=comp[2]
		end=datetime.datetime.strptime(enda, '%Y-%m-%d').strftime('%Y-%m-%d %H:%M:%S')
		mob=DukaMatumiziModels.objects.all()
		for m in mob:
			if m.company==company:
				if m.pk:
				
					mog=datetime.datetime.strptime(m.Tarehe, '%Y-%m-%d  %H:%M:%S').strftime('%Y-%m-%d %H:%M:%S')
				
					DukaMatumiziModels.objects.filter(pk=m.pk, company=company).update(Tarehe=mog)

		
		return DukaMatumiziModels.objects.filter(company=company,  Tarehe__gte=start, Tarehe__lte=end).order_by('-pk')
	

