class TotalstockBorrowedView(APIView):
	queryset = DukaProductsModel.objects.all()
	serializer_class = DukaMadeniSerializer
	permission_classes = [AllowAny]

	def get(self, request, format=None):
		company = self.request.GET.get('company', None)
		momo = DukaMadeniModels.objects.filter(company=company)
		momoall = DukaMadeniModels.objects.all()
	
		total = ( DukaMadeniModels.objects.filter(company=company).aggregate(totol=Sum('Total'))['totol']) 
		total1 = ( DukaMadeniModels.objects.filter(company=company).aggregate(totol1=Sum('Profit'))['totol1']) 
		total2 = ( DukaMadeniModels.objects.filter(company=company).aggregate(totol2=Sum('Quantity'))['totol2']) 
	
		total_borowed=total
		total_stock_borrowed_quantity=total2
		total_profit_borrowed=total1
		context={
            'total_stock_borrowed':total_borowed,
            'total_stock_profit':total_profit_borrowed,
            'total_stock_borrowed_quantity':total_stock_borrowed_quantity,
        }
		return Response(context, status=HTTP_200_OK)
	

