	lookup_field = 'pk'
	# serializer_class = RegisterSerializer
	permission_classes = [AllowAny]
	
	
	def get_serializer_class(self):
		username = self.kwargs['username']
		mosx = Register.objects.filter(Username = username)
		testl = WakalaWorkers.objects.filter(user=username)
		testr = WakalaMmiliki.objects.filter(user=username)
		testz = OrdersWorkerModel.objects.filter(user=username)
