class MalipoSearchView( generics.CreateAPIView, generics.ListAPIView):
	lookup_field = 'pk'
	serializer_class = RegisterSerializer
	permission_classes = [AllowAny]

	def get_queryset(self):
		username = self.kwargs['username']
		find_username = self.kwargs['find_username']
		mog = Register.objects.all()
		for n in mog:
			if n.Username.lower() == find_username.lower():
				return Register.objects.filter(company_username = username, Username__icontains=find_username)
			elif n.jina.lower() == find_username.lower():
				return Register.objects.filter(company_username = username, jina__icontains=find_username)
			elif n.TSD == find_username:
				return Register.objects.filter(company_username = username, TSD=find_username)
			elif n.Account_no == find_username:
				return Register.objects.filter(company_username = username, Account_no=find_username)
			elif n.kata.lower() == find_username.lower():
				return Register.objects.filter(company_username = username, kata__icontains=find_username)
			elif n.wilaya.lower() == find_username.lower():
				return Register.objects.filter(company_username = username, wilaya__icontains=find_username)
			elif n.mkoa.lower() == find_username.lower():
				return Register.objects.filter(company_username = username, mkoa_icontains=find_username)
			elif n.Simu == find_username:
				return Register.objects.filter(company_username = username, Simu=find_username)
			elif n.generated_id == find_username:
				return Register.objects.filter(company_username = username, generated_id=find_username)
			elif n.file_no == find_username:
				return Register.objects.filter(company_username = username, file_no=find_username)
		



